// 1) Status code & response time
pm.test("HTTP status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response time is less than 3000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(3000);
});

// 2) الـ API ده بيرجع Content-Type: text/html غالباً، فبنعمل parse يدوي
let jsonData;
pm.test("Body is a valid JSON", function () {
    jsonData = JSON.parse(pm.response.text());
    pm.expect(jsonData).to.be.an("object");
});

// 3) Body structure
pm.test("responseCode inside body is 200", function () {
    pm.expect(jsonData.responseCode).to.eql(200);
});

pm.test("products is a non-empty array", function () {
    pm.expect(jsonData.products).to.be.an("array").that.is.not.empty;
});

// 4) Fields لكل منتج
pm.test("Each product has required fields with correct types", function () {
    jsonData.products.forEach(function (p) {
        pm.expect(p.id, "id").to.be.a("number");
        pm.expect(p.name, "name of id " + p.id).to.be.a("string").and.not.empty;
        pm.expect(p.price, "price of id " + p.id).to.be.a("string").and.match(/^Rs\. \d+$/);
        pm.expect(p.brand, "brand of id " + p.id).to.be.a("string").and.not.empty;
        pm.expect(p.category, "category of id " + p.id).to.be.an("object");
        pm.expect(p.category.usertype.usertype, "usertype of id " + p.id).to.be.a("string");
        pm.expect(p.category.category, "category name of id " + p.id).to.be.a("string").and.not.empty;
    });
});

// 5) Business rules
pm.test("All product ids are unique", function () {
    const ids = jsonData.products.map(p => p.id);
    pm.expect(new Set(ids).size).to.eql(ids.length);
});

pm.test("usertype is one of Men / Women / Kids", function () {
    const valid = ["Men", "Women", "Kids"];
    jsonData.products.forEach(function (p) {
        pm.expect(valid, "usertype of id " + p.id).to.include(p.category.usertype.usertype);
    });
});

pm.test("Price is a positive number", function () {
    jsonData.products.forEach(function (p) {
        const value = parseInt(p.price.replace("Rs. ", ""), 10);
        pm.expect(value, "price of id " + p.id).to.be.above(0);
    });
});

